	private int importQuantities(Quantity[] quantities) {
		Objects.requireNonNull(quantities, "quantities");
		if (quantities.length == 0) {
			return -2;
		}
		// Provider getters can reenter the raw region API, whose operations use the same arena builder.
		// Snapshot each admitted declaration before touching that builder; at most one entry per dimension survives.
		QuantitySnapshot snapshots = null;
		long seen = 0L;
		for (Quantity quantity : quantities) {
			if (!reserve(1L)) {
				return -1;
			}
			Objects.requireNonNull(quantity, "quantity");
			int dimension = dimensionId(quantity.dimension());
			long bit = 1L << dimension - 1;
			if ((seen & bit) != 0L) {
				throw new IllegalArgumentException("duplicate physical quantity");
			}
			seen |= bit;
			double lower = quantity.lower();
			double point = quantity.point();
			double upper = quantity.upper();
			PackedSearchBudget.checkCancellation();
			if (!Double.isFinite(lower) || !Double.isFinite(point) || !Double.isFinite(upper)
					|| lower < 0.0d || lower > point || point > upper) {
				throw new IllegalArgumentException("cost interval must be finite, non-negative, ordered, and lineaged");
			}
			Lineage lineage = Objects.requireNonNull(quantity.lineage(), "lineage");
			PackedSearchBudget.checkCancellation();
			// Match the arena's mathematical equality, including both signs of zero.
			if (lineage == Lineage.UNKNOWN && lower == upper) {
				return -2;
			}
			int lineageId = switch (lineage) {
			case EXACT -> 0;
			case UNKNOWN -> PackedCostVectorArena.MIXED_LINEAGE_ID;
			};
			if (!reserve(1L)) {
				return -1;
			}
			if (!memory(64L)) {
				return 0;
			}
			snapshots = new QuantitySnapshot(dimension, lower, point, upper, lineageId, snapshots);
		}
		PackedCostVectorArena arena = owner.vectors(generation);
		if (!reserve(arena.builderResetWork())) {
			return -1;
		}
		arena.resetBuilderToUnknown();
		for (QuantitySnapshot snapshot = snapshots; snapshot != null; snapshot = snapshot.previous) {
			try {
				if (!arena.setBuilderInterval(snapshot.dimension, snapshot.lower, snapshot.point, snapshot.upper,
						snapshot.lineageId, owner,
						owner.memory(generation))) {
					refuse(PackedPhysicalRegion.Status.RESOURCE_REFUSED);
					return 0;
				}
			} catch (PackedProviderWork.Exhausted failure) {
				if (failure != owner.ownedStrategyStop) {
					throw failure;
				}
				return -1;
			}
		}
		try {
			int vector = arena.internBuilder(owner, owner.memory(generation), 96L);
			if (vector == 0) {
				refuse(PackedPhysicalRegion.Status.RESOURCE_REFUSED);
			}
			return vector;
		} catch (PackedProviderWork.Exhausted failure) {
			if (failure != owner.ownedStrategyStop) {
				throw failure;
			}
			return -1;
		}
	}

